import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.CHeM0PsO.js";const o="/images/aliya-web-auth.webp",s="/images/aliya-web-token-1.webp",l="/images/aliya-web-token-2.webp",n="/images/aliya-web-pc.webp",p="/images/aliya-web-mobile.webp",g="/images/aliya-web-operation.webp",k=JSON.parse('{"title":"Aliya Web","description":"","frontmatter":{},"headers":[],"relativePath":"guide/aliya-web.md","filePath":"guide/aliya-web.md","lastUpdated":1789295632000}'),c={name:"guide/aliya-web.md"};function h(d,a,b,m,u,_){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="aliya-web" tabindex="-1">Aliya Web <a class="header-anchor" href="#aliya-web" aria-label="Permalink to &quot;Aliya Web&quot;">​</a></h1><p>Aliya Web 是与阈界人格社区同级的独立项目——基于社区智能体功能开发的 Aliya 聊天终端，仿照原版游戏 UI 设计，电脑手机均可访问使用。<a href="https://aliya.liminalselves.top" target="_blank" rel="noreferrer"><strong>传送门</strong></a></p><h2 id="登录说明" tabindex="-1">登录说明 <a class="header-anchor" href="#登录说明" aria-label="Permalink to &quot;登录说明&quot;">​</a></h2><ol><li>首次使用，需要进行 Misskey 授权或填写 Token。<strong>推荐使用 Misskey 授权登录。</strong> 点击后会跳转到图示界面，选择自己的账号登录即可。如果没有显示自己的账号，则需要点击添加账户，输入自己的账号密码登录。</li></ol><p><img src="'+o+'" alt="授权"></p><p>如果想要使用 token 登录，可以按照下列流程操作，普通用户不推荐使用这种登录方式。大致流程为：设置 =&gt; 连接服务 =&gt; 生成访问令牌 =&gt; 启用所有权限 =&gt; 复制。</p><p><img src="'+s+'" alt="创建token"></p><p><img src="'+l+'" alt="生成token"></p><p>然后回到登录界面粘贴 token 即可登录。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>访问令牌具有账户的完整访问权限，请妥善保管。若不慎泄露，参照<a href="/guide/faq#api-token-泄露了怎么办">常见问题</a>立即删除。</p></div><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><p>电脑版的界面如下：</p><p><img src="'+n+'" alt="PC 端界面"></p><p>手机版的界面如下：</p><p><img src="'+p+'" alt="手机端界面"></p><h3 id="operation-主设置窗口" tabindex="-1">Operation：主设置窗口 <a class="header-anchor" href="#operation-主设置窗口" aria-label="Permalink to &quot;Operation：主设置窗口&quot;">​</a></h3><p>包含<strong>会话控制、模型设置、图片生成、主动消息、记忆配置、文风选择</strong>标签页。</p><p><img src="'+g+'" alt="会话面板"></p><ul><li><strong>会话控制</strong>：点击会话列表中的会话即可加载。可以对单个对话进行重命名，也可以删除会话。<strong>删除操作不可逆，请慎重</strong>。面板中可以直接创建新会话。新会话起码要有一条消息，否则新会话不会被记录到会话列表。如果出现奇怪的消息显示问题，重新切换一次对话可能能解决。</li><li><strong>模型设置</strong>：同<a href="/guide/agent/chat#模型">模型</a>。</li><li><strong>图片生成</strong>：同<a href="/guide/agent/chat#生图">生图</a>。</li><li><strong>主动消息</strong>：同<a href="/guide/agent/proactive">主动消息</a>。</li><li><strong>记忆配置</strong>：开启记忆功能体验更佳。暂时不支持直接操作，需要跳转 Misskey 配置，详见<a href="/guide/agent/memory">记忆</a>。</li><li><strong>文风选择</strong>：面板中会显示当前广场中的文风，点击切换文风会自动添加到订阅中。如果没有特殊需求，使用默认值（标准文风特殊版）即可。</li></ul><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><p>设置 BGM 播放和使用的 token。</p><h3 id="聊天窗口" tabindex="-1">聊天窗口 <a class="header-anchor" href="#聊天窗口" aria-label="Permalink to &quot;聊天窗口&quot;">​</a></h3><p>分为消息区、面板区和输入框：</p><ul><li><strong>消息区</strong>：显示消息和图片，图片可以点击放大和鼠标滚轮缩放，向上滑动会自动拉取历史消息。</li><li><strong>面板区</strong>：经典面板，大部分属性显示都只是一个固定值，四个按钮按了其实也没什么用（所以不用担心憋似），但是心率是 Aliya 的实时心率。</li><li><strong>输入框</strong>：点击图片图标可以上传图片文件。</li></ul><h2 id="遇到异常" tabindex="-1">遇到异常？ <a class="header-anchor" href="#遇到异常" aria-label="Permalink to &quot;遇到异常？&quot;">​</a></h2><p>提示「休息一下马上回复」、429 错误等问题的处理方式，参见<a href="/guide/faq">常见问题</a>。</p>',26)])])}const y=e(c,[["render",h]]);export{k as __pageData,y as default};
